Here is the commit message:
btrfs: zoned: don't skip block groups with 100% zone unusable

Commit f4a9f219411f ("btrfs: do not delete unused block group if it may be
used soon") changed the behaviour of deleting unused block-groups on zoned
filesystems. Starting with this commit, we're using
btrfs_space_info_used() to calculate the number of used bytes in a
space_info. But btrfs_space_info_used() also accounts
btrfs_space_info::bytes_zone_unusable as used bytes.

So if a block group is 100% zone_unusable it is skipped from the deletion
step.

In order not to skip fully zone_unusable block-groups, also check if the
block-group has bytes left that can be used on a zoned filesystem.

Fixes: f4a9f219411f ("btrfs: do not delete unused block group if it may be used soon")
CC: stable@vger.kernel.org # 6.1+
Reviewed-by: Filipe Manana <fdmanana@suse.com>
Signed-off-by: Johannes Thumshirn <johannes.thumshirn@wdc.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>

Here is the root cause:
The bug was caused by a change in the logic for deleting unused block groups in zoned filesystems, where the function `btrfs_space_info_used()` incorrectly accounted for fully zone unusable block groups as used, leading to their unintended exclusion from deletion. This resulted in block groups that were 100% zone unusable being skipped during the cleanup process, which could lead to inefficient space management.

Here is the patch:
  */
 void btrfs_delete_unused_bgs(struct btrfs_fs_info *fs_info)
 {
 	LIST_HEAD(retry_list);
 	struct btrfs_block_group *block_group;
 	struct btrfs_space_info *space_info;
 	struct btrfs_trans_handle *trans;
 	const bool async_trim_enabled = btrfs_test_opt(fs_info, DISCARD_ASYNC);
 	int ret = 0;

 	if (!test_bit(BTRFS_FS_OPEN, &fs_info->flags))
 		return;

 	if (btrfs_fs_closing(fs_info))
 		return;

 	/*
 	 * Long running balances can keep us blocked here for eternity, so
 	 * simply skip deletion if we're unable to get the mutex.
 	 */
 	if (!mutex_trylock(&fs_info->reclaim_bgs_lock))
 		return;

 	spin_lock(&fs_info->unused_bgs_lock);
 	while (!list_empty(&fs_info->unused_bgs)) {
 		u64 used;
 		int trimming;

 		block_group = list_first_entry(&fs_info->unused_bgs,
 					       struct btrfs_block_group,
 					       bg_list);
 		list_del_init(&block_group->bg_list);

 		space_info = block_group->space_info;

 		if (ret || btrfs_mixed_space_info(space_info)) {
 			btrfs_put_block_group(block_group);
 			continue;
 		}
 		spin_unlock(&fs_info->unused_bgs_lock);

 		btrfs_discard_cancel_work(&fs_info->discard_ctl, block_group);

 		/* Don't want to race with allocators so take the groups_sem */
 		down_write(&space_info->groups_sem);

 		/*
 		 * Async discard moves the final block group discard to be prior
 		 * to the unused_bgs code path.  Therefore, if it's not fully
 		 * trimmed, punt it back to the async discard lists.
 		 */
 		if (btrfs_test_opt(fs_info, DISCARD_ASYNC) &&
 		    !btrfs_is_free_space_trimmed(block_group)) {
 			trace_btrfs_skip_unused_block_group(block_group);
 			up_write(&space_info->groups_sem);
 			/* Requeue if we failed because of async discard */
 			btrfs_discard_queue_work(&fs_info->discard_ctl,
 						 block_group);
 			goto next;
 		}

 		spin_lock(&space_info->lock);
 		spin_lock(&block_group->lock);
 		if (btrfs_is_block_group_used(block_group) || block_group->ro ||
 		    list_is_singular(&block_group->list)) {
 			/*
 			 * We want to bail if we made new allocations or have
 			 * outstanding allocations in this block group.  We do
 			 * the ro check in case balance is currently acting on
 			 * this block group.
 			 *
 			 * Also bail out if this is the only block group for its
 			 * type, because otherwise we would lose profile
 			 * information from fs_info->avail_*_alloc_bits and the
 			 * next block group of this type would be created with a
 			 * "single" profile (even if we're in a raid fs) because
 			 * fs_info->avail_*_alloc_bits would be 0.
 			 */
 			trace_btrfs_skip_unused_block_group(block_group);
 			spin_unlock(&block_group->lock);
 			spin_unlock(&space_info->lock);
 			up_write(&space_info->groups_sem);
 			goto next;
 		}

 		/*
 		 * The block group may be unused but there may be space reserved
 		 * accounting with the existence of that block group, that is,
 		 * space_info->bytes_may_use was incremented by a task but no
 		 * space was yet allocated from the block group by the task.
 		 * That space may or may not be allocated, as we are generally
 		 * pessimistic about space reservation for metadata as well as
 		 * for data when using compression (as we reserve space based on
 		 * the worst case, when data can't be compressed, and before
 		 * actually attempting compression, before starting writeback).
 		 *
 		 * So check if the total space of the space_info minus the size
 		 * of this block group is less than the used space of the
 		 * space_info - if that's the case, then it means we have tasks
 		 * that might be relying on the block group in order to allocate
 		 * extents, and add back the block group to the unused list when
 		 * we finish, so that we retry later in case no tasks ended up
 		 * needing to allocate extents from the block group.
 		 */
 		used = btrfs_space_info_used(space_info, true);
-		if (space_info->total_bytes - block_group->length < used) {
+		if (space_info->total_bytes - block_group->length < used &&
+		    block_group->zone_unusable < block_group->length) {
 			/*
 			 * Add a reference for the list, compensate for the ref
 			 * drop under the "next" label for the
 			 * fs_info->unused_bgs list.
 			 */
 			btrfs_get_block_group(block_group);
 			list_add_tail(&block_group->bg_list, &retry_list);

 			trace_btrfs_skip_unused_block_group(block_group);
 			spin_unlock(&block_group->lock);
 			spin_unlock(&space_info->lock);
 			up_write(&space_info->groups_sem);
 			goto next;
 		}

 		spin_unlock(&block_group->lock);
 		spin_unlock(&space_info->lock);

 		/* We don't want to force the issue, only flip if it's ok. */
 		ret = inc_block_group_ro(block_group, 0);
 		up_write(&space_info->groups_sem);
 		if (ret < 0) {
 			ret = 0;
 			goto next;
 		}

 		ret = btrfs_zone_finish(block_group);
 		if (ret < 0) {
 			btrfs_dec_block_group_ro(block_group);
 			if (ret == -EAGAIN)
 				ret = 0;
 			goto next;
 		}

 		/*
 		 * Want to do this before we do anything else so we can recover
 		 * properly if we fail to join the transaction.
 		 */
 		trans = btrfs_start_trans_remove_block_group(fs_info,
 						     block_group->start);
 		if (IS_ERR(trans)) {
 			btrfs_dec_block_group_ro(block_group);
 			ret = PTR_ERR(trans);
 			goto next;
 		}

 		/*
 		 * We could have pending pinned extents for this block group,
 		 * just delete them, we don't care about them anymore.
 		 */
 		if (!clean_pinned_extents(trans, block_group)) {
 			btrfs_dec_block_group_ro(block_group);
 			goto end_trans;
 		}

 		/*
 		 * At this point, the block_group is read only and should fail
 		 * new allocations.  However, btrfs_finish_extent_commit() can
 		 * cause this block_group to be placed back on the discard
 		 * lists because now the block_group isn't fully discarded.
 		 * Bail here and try again later after discarding everything.
 		 */
 		spin_lock(&fs_info->discard_ctl.lock);
 		if (!list_empty(&block_group->discard_list)) {
 			spin_unlock(&fs_info->discard_ctl.lock);
 			btrfs_dec_block_group_ro(block_group);
 			btrfs_discard_queue_work(&fs_info->discard_ctl,
 						 block_group);
 			goto end_trans;
 		}
 		spin_unlock(&fs_info->discard_ctl.lock);

 		/* Reset pinned so btrfs_put_block_group doesn't complain */
 		spin_lock(&space_info->lock);
 		spin_lock(&block_group->lock);

 		btrfs_space_info_update_bytes_pinned(fs_info, space_info,
 						     -block_group->pinned);
 		space_info->bytes_readonly += block_group->pinned;
 		block_group->pinned = 0;

 		spin_unlock(&block_group->lock);
 		spin_unlock(&space_info->lock);

 		/*
 		 * The normal path here is an unused block group is passed here,
 		 * then trimming is handled in the transaction commit path.
 		 * Async discard interposes before this to do the trimming
 		 * before coming down the unused block group path as trimming
 		 * will no longer be done later in the transaction commit path.
 		 */
 		if (!async_trim_enabled && btrfs_test_opt(fs_info, DISCARD_ASYNC))
 			goto flip_async;

 		/*
 		 * DISCARD can flip during remount. On zoned filesystems, we
 		 * need to reset sequential-required zones.
 		 */
 		trimming = btrfs_test_opt(fs_info, DISCARD_SYNC) ||
 				btrfs_is_zoned(fs_info);

 		/* Implicit trim during transaction commit. */
 		if (trimming)
 			btrfs_freeze_block_group(block_group);

 		/*
 		 * Btrfs_remove_chunk will abort the transaction if things go
 		 * horribly wrong.
 		 */
 		ret = btrfs_remove_chunk(trans, block_group->start);

 		if (ret) {
 			if (trimming)
 				btrfs_unfreeze_block_group(block_group);
 			goto end_trans;
 		}

 		/*
 		 * If we're not mounted with -odiscard, we can just forget
 		 * about this block group. Otherwise we'll need to wait
 		 * until transaction commit to do the actual discard.
 		 */
 		if (trimming) {
 			spin_lock(&fs_info->unused_bgs_lock);
 			/*
 			 * A concurrent scrub might have added us to the list
 			 * fs_info->unused_bgs, so use a list_move operation
 			 * to add the block group to the deleted_bgs list.
 			 */
 			list_move(&block_group->bg_list,
 				  &trans->transaction->deleted_bgs);
 			spin_unlock(&fs_info->unused_bgs_lock);
 			btrfs_get_block_group(block_group);
 		}
 end_trans:
 		btrfs_end_transaction(trans);
 next:
 		btrfs_put_block_group(block_group);
 		spin_lock(&fs_info->unused_bgs_lock);
 	}
 	list_splice_tail(&retry_list, &fs_info->unused_bgs);
 	spin_unlock(&fs_info->unused_bgs_lock);
 	mutex_unlock(&fs_info->reclaim_bgs_lock);
 	return;

 flip_async:
 	btrfs_end_transaction(trans);
 	spin_lock(&fs_info->unused_bgs_lock);
 	list_splice_tail(&retry_list, &fs_info->unused_bgs);
 	spin_unlock(&fs_info->unused_bgs_lock);
 	mutex_unlock(&fs_info->reclaim_bgs_lock);
 	btrfs_put_block_group(block_group);
 	btrfs_discard_punt_unused_bgs_list(fs_info);
 }



